# camel_to_snake :: 'HelloWorld'
import re

def camel_to_snake(s):
    return re.sub(r'(?<!^)(?=[A-Z])', '_', s).lower()

if __name__ == '__main__':
    print(camel_to_snake('HelloWorld'))

